<div class="hero"><div><p class="eyebrow">UN CLUB. SETTE MONDI.</p><div class="profile-heading"><span id="profile-avatar" class="hero-avatar" hidden></span><div><h1 id="title">Club House</h1><p id="subtitle">Tutti i manager IMC. Tutta la carriera nei club.</p></div></div><div class="hero-tags"><span>Carriera globale</span><span>Club e Nations</span><span>IMC-001–IMC-007</span></div></div><div class="hero-mark" aria-hidden="true">CH<span>CLUB HOUSE</span></div></div></header><main>
<nav class="hub-sections" aria-label="Sezioni Club House"><a href="/clubhouse/" aria-current="page">Mondi e assegnazioni</a><a href="/clubhouse/?view=career">IMC Career</a><a href="/clubhouse/?view=ranking">IMC Ranking</a><a href="/clubhouse/?view=timeline">IMC Timeline</a><a href="/clubhouse/?view=trophies">IMC Trophy Room</a><a href="/clubhouse/?view=h2h">IMC H2H</a></nav>
<?php if($failed): ?><p role="alert">Le assegnazioni sono temporaneamente non disponibili.</p><a href="/clubhouse/">Riprova →</a><?php else: ?>
<nav id="assignment-worlds" class="worlds" aria-label="Mondi IMC"><?php foreach($worlds as $w): $url=(['GW001'=>'/roadtohistory/','GW005'=>'/halloffamers/','GW009'=>'/kickoff/','GW010'=>'/sensiblesocceracademy/','GW011'=>'/subbuteosuperleague/','GW004'=>'/worldleague/','GW006'=>'/masterleagueworld/'])[$w['gw']]; ?><a class="world manager-card" href="<?=ch_escape($url)?>"><small><?=ch_escape($w['code'])?> ↗</small><strong><?=ch_escape($w['name'])?></strong><span class="world-counts"><span><b><?=ch_escape($w['active_clubs'])?></b>Active</span><span><b><?=count($coached[$w['gw']]??[])?></b>Allenate</span></span></a><?php endforeach ?></nav>
<section aria-labelledby="managers-title"><span class="eyebrow">Le persone del Club</span><h2 id="managers-title">Manager e assegnazioni</h2><div id="scope-tabs" class="assignment-tabs" aria-label="Stato incarichi"><button data-mode="active" aria-pressed="true">Attivi</button><button data-mode="ended" aria-pressed="false">Storico</button></div><div class="controls"><label id="search-label">Manager<input id="search" type="search" aria-label="Cerca manager o squadra" placeholder="Cerca manager o squadra…"></label><label>Game World<select id="world" aria-label="Filtra per mondo"><option value="">Tutti i sette IMC</option><?php foreach($worlds as $w): ?><option value="<?=ch_escape($w['gw'])?>"><?=ch_escape($w['code'].' · '.$w['name'])?></option><?php endforeach ?></select></label><button id="retry" type="button" aria-label="Aggiorna assegnazioni">↻</button></div><p id="summary" role="status" aria-live="polite"></p><div id="cards" class="manager-grid assignment-grid"></div><noscript>Attiva JavaScript per consultare le assegnazioni.</noscript></section>
<script>
const worlds=<?=json_encode($worlds,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>,rows=<?=json_encode($assignments,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>,today=<?=json_encode($today)?>;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
ClubhousePortraits.setPeople(rows);
const date=v=>v?v.slice(0,10).split('-').reverse().join('/'):'—';let mode='active';
const search=document.getElementById('search'),filter=document.getElementById('world'),cards=document.getElementById('cards');
function render(){const managers=new Map();let count=0;const q=search.value.trim().toLocaleLowerCase('it');
for(const a of rows){const active=(!a.start_date||a.start_date<=today)&&(!a.end_date||a.end_date>=today);const ended=a.end_date&&a.end_date<today;if(!(mode==='active'?active:ended)||filter.value&&a.game_world_id!==filter.value)continue;const id=a.manager_id;if(!managers.has(id))managers.set(id,{name:a.full_name,id,items:[]});managers.get(id).items.push(a)}
const visible=[...managers.values()].filter(m=>[m.name,...m.items.map(a=>a.team_name)].join(' ').toLocaleLowerCase('it').includes(q));
cards.innerHTML=visible.map(m=>'<article class="manager-card assignment-card"><div class="identity assignment-identity">'+ClubhousePortraits.portrait(m.id,'bust')+'<div class="assignment-person"><h2><span>'+esc(m.name.trim().split(/\s+/)[0])+'</span><span>'+esc(m.name.trim().split(/\s+/).slice(1).join(' '))+'</span></h2><small class="assignment-id-label">Manager ID</small><strong class="assignment-id">'+esc(m.id)+'</strong></div></div>'+worlds.map(w=>{const aa=m.items.filter(a=>a.game_world_id===w.gw);count+=aa.length;if(!aa.length)return '';return '<div class="group"><h4>'+esc(w.code+' · '+w.name)+'</h4>'+aa.map(a=>{const src=String(a.image_url||'').replace(/^http:/,'https:');return '<div class="team">'+(/^https:\/\//.test(src)?'<img loading="lazy" src="'+esc(src)+'" alt="">':'')+'<div><strong>'+esc(a.team_name||'Squadra non disponibile')+'</strong><small>'+(a.assignment_type==='national_team'?'Nazionale':'Club')+' · '+date(a.start_date)+(a.end_date?' – '+date(a.end_date):'')+'</small><small class="status '+(mode==='ended'?'ended':'')+'">'+(mode==='ended'?'Ended':'Active')+'</small></div></div>'}).join('')+'</div>'}).join('')+'</article>').join('')||'<p>Nessuna assegnazione trovata.</p>';
document.getElementById('summary').textContent=visible.length+' manager · '+count+' incarichi';cards.querySelectorAll('img').forEach(i=>i.onerror=()=>i.hidden=true)}
document.getElementById("retry").onclick=()=>location.reload();search.oninput=render;filter.onchange=render;document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;document.querySelectorAll('[data-mode]').forEach(t=>t.setAttribute('aria-pressed',String(t===b)));render()});render();
</script><?php endif ?></main><footer>ITALIAN MASTERS CLUB · CLUBHOUSE</footer>
<nav class="global-nav" aria-label="Navigazione principale"><a href="/clubhouse/" aria-current="page">Club House</a><button id="nav-worlds" type="button">Game World</button></nav>
<dialog id="world-dialog"><div class="dialog-heading"><h2>Scegli il tuo Game World</h2><button id="close-worlds" type="button" aria-label="Chiudi Game World">×</button></div><div id="world-links" class="world-links"></div></dialog>
<script>
(()=>{const dialog=document.getElementById('world-dialog'),links=document.getElementById('world-links');document.querySelectorAll('#assignment-worlds>a').forEach(a=>{const link=document.createElement('a');link.href=a.href;link.innerHTML=a.querySelector('small').outerHTML+a.querySelector('strong').outerHTML;links.append(link)});document.getElementById('open-worlds').onclick=document.getElementById('nav-worlds').onclick=()=>dialog.showModal();document.getElementById('close-worlds').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}})})();
</script></body></html>

